//! Command allocators and command lists: D3D12 commands are encoded into an
//! `MTL4CommandBuffer` at record time.
//!
//! Barriers (memo §3.8, pitfall 7): the first encoder of a list and the first
//! encoder after any `ResourceBarrier` (or internal producer such as a copy or
//! ExecuteIndirect expansion) start with a queue barrier all-stages →
//! all-stages; a barrier inside a render pass ends the pass. Encoder
//! boundaries alone do not serialize: D3D12 requires an explicit barrier for
//! every cross-state dependency, except render-target/depth writes that stay
//! in the same state across passes, which are tracked per resource and get a
//! fragment → fragment barrier when a later pass attaches the same resource.
//! Whole-subresource clears are deferred and folded into the next render
//! pass's load action (`AW2_LEGACY_BARRIERS=1` restores the old model).

use super::binding::{new_argument_table, MtlArgumentTable, RootState, UploadRing};
use super::pipeline::{vertex_buffer_index, ComputePipeline, GraphicsPipeline, MAX_VERTEX_SLOTS};
use super::queue::{ListType, MtlCommandBuffer};
use super::encstats as stats;
use super::passtiming as pt;
use super::resource::{push_subrange, Resource, SubRange};
use crate::types::Rect;
use dxil_metal::runtime::{
    ARGUMENT_BUFFER_BIND_POINT, ARGUMENT_BUFFER_DRAW_ARGUMENTS_BIND_POINT, ARGUMENT_BUFFER_UNIFORMS_BIND_POINT, DESCRIPTOR_HEAP_BIND_POINT, NON_INDEXED_DRAW,
    SAMPLER_HEAP_BIND_POINT, VERTEX_BUFFER_BIND_POINT,
};
use objc2::rc::Retained;
use objc2::Message;
use objc2::runtime::ProtocolObject;
use objc2_metal::*;
use std::sync::{Arc, Mutex};

pub type MtlAllocator = ProtocolObject<dyn MTL4CommandAllocator>;

/// On iOS (6 GiB unified Jetsam limit), reuse `IcbRing` and GPU-written `icb_scratch`
/// across closed render passes (rewound strictly after `endEncoding()`, synchronized by a
/// cross-encoder `barrierAfterQueueStages(Vertex|Fragment, Vertex|Dispatch)`).
fn icb_reuse_enabled() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        std::env::var_os("PORT_IOS_REUSE_ICB")
            .map(|v| v != "0")
            .unwrap_or(cfg!(target_os = "ios"))
    })
}

/// Maximum indirect commands accumulated inside a single open Metal render pass on iOS
/// (`PORT_IOS_ICB_PASS_CAP`, default `65536`) before splitting via `end_encoder()` (which
/// calls `endEncoding()`, stores attachments, rewinds `IcbRing` + `icb_scratch`, and
/// reopens the next pass with `LoadAction::Load` + a TBDR-safe cross-encoder WAR barrier).
/// With compact 6-slot ICBs (~793 bytes/cmd), 65536 cmds is capped at <= 50 MiB per pass
/// while avoiding 2–3 mid-pass TBDR store+load flushes per frame.
fn ios_icb_pass_cap() -> u32 {
    static CAP: std::sync::OnceLock<u32> = std::sync::OnceLock::new();
    *CAP.get_or_init(|| {
        std::env::var("PORT_IOS_ICB_PASS_CAP")
            .ok()
            .and_then(|v| v.trim().parse::<u32>().ok())
            .unwrap_or(65536)
    })
}

static IOS_ICB_PASS_SPLITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// Return and reset the count of iOS ICB render-pass splits since the previous call.
pub fn take_ios_icb_pass_splits() -> u64 {
    IOS_ICB_PASS_SPLITS.swap(0, std::sync::atomic::Ordering::Relaxed)
}

pub struct CommandAllocator {
    pub a: Retained<MtlAllocator>,
    pub kind: ListType,
    /// Transient GPU memory (CPU-written root argument images & params) of lists recorded here.
    pub ring: Arc<Mutex<UploadRing>>,
    /// GPU-written, GPU-read transient buffers for `ExecuteIndirect` ICB expansion
    /// (`range_out`, `tlab_out`, `args_out`), rewindable between GPU-synchronized batches.
    pub icb_scratch: Arc<Mutex<UploadRing>>,
    /// Retired acceleration structures replaced while recording on this allocator;
    /// kept alive until [`Self::reset`] (when the app guarantees GPU completion).
    pub rt_keep: Arc<Mutex<Vec<crate::rt::accel::Retired>>>,
    /// GPU-encoded `ExecuteIndirect` commands of lists recorded here.
    pub icbs: Arc<Mutex<super::indirect_icb::IcbRing>>,
}
unsafe impl Send for CommandAllocator {}
unsafe impl Sync for CommandAllocator {}

impl CommandAllocator {
    pub fn new(kind: ListType) -> Option<CommandAllocator> {
        let d = super::device()?;
        Some(CommandAllocator {
            a: d.dev.newCommandAllocator()?,
            kind,
            ring: Arc::default(),
            icb_scratch: Arc::default(),
            rt_keep: Arc::default(),
            icbs: Arc::default(),
        })
    }
    /// `ID3D12CommandAllocator::Reset` (the app guarantees GPU completion).
    pub fn reset(&self) {
        self.a.reset();
        self.ring.lock().unwrap().reset();
        self.icb_scratch.lock().unwrap().reset();
        self.rt_keep.lock().unwrap().clear();
        self.icbs.lock().unwrap().reset();
    }
}

/// What an RTV/DSV descriptor (host memory, 32 bytes) holds.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct TargetView {
    /// `*const Resource` (not owning; D3D12 descriptors hold no reference).
    pub resource: usize,
    pub format: u32,
    pub mip: u16,
    pub plane: u16,
    pub first_slice: u32,
    pub slices: u32,
    /// `MTLTextureType` raw value of the view.
    pub ty: u32,
    pub flags: u32,
}
const _: () = assert!(std::mem::size_of::<TargetView>() == 32);

/// `D3D12_RENDER_TARGET_VIEW_DESC` / `D3D12_DEPTH_STENCIL_VIEW_DESC` as raw
/// words: RTV = Format, ViewDimension, union @8 (16 bytes); DSV = Format,
/// ViewDimension, Flags, union @12 (12 bytes).
pub mod view_flags {
    pub const DSV_READ_ONLY_DEPTH: u32 = 1;
    pub const DSV_READ_ONLY_STENCIL: u32 = 2;
    pub const IS_DSV: u32 = 0x100;
}

fn clamp_slices(total: u32, first: u32, size: u32) -> (u32, u32) {
    let f = first.min(total);
    let rem = total.saturating_sub(f);
    (f, if size == u32::MAX { rem } else { size.min(rem) })
}

impl TargetView {
    pub const NULL: TargetView = TargetView { resource: 0, format: 0, mip: 0, plane: 0, first_slice: 0, slices: 0, ty: 0, flags: 0 };

    fn whole(r: &Resource, fmt: MTLPixelFormat) -> TargetView {
        r.register_ptr();
        let arr = if r.desc.Dimension == crate::types::dim::TEXTURE3D { r.desc.depth() } else { r.desc.array_size() };
        let ty = match r.texture() {
            Some(t) => t.textureType().0 as u32,
            None => 0,
        };
        TargetView { resource: r as *const Resource as usize, format: fmt.0 as u32, mip: 0, plane: 0, first_slice: 0, slices: arr, ty, flags: 0 }
    }

    /// `CreateRenderTargetView(resource, desc)`; `desc` = 6 u32 words
    /// (Format, ViewDimension, union) or `None`.
    pub fn rtv(r: &Resource, desc: Option<&[u32; 6]>) -> Result<TargetView, String> {
        if r.texture().is_none() {
            return Err("RTV of a buffer is not supported".into());
        }
        let Some(d) = desc else { return Ok(Self::whole(r, r.mtl_format)) };
        let fmt = crate::format::view_format(d[0], r.mtl_format);
        let mut v = Self::whole(r, fmt);
        let u = &d[2..];
        let arr = r.desc.array_size();
        match d[1] {
            2 => {
                v.mip = u[0] as u16; // TEXTURE1D
                v.slices = 1;
            }
            3 | 5 => {
                // TEXTURE1DARRAY / TEXTURE2DARRAY {Mip, First, Size[, Plane]}
                v.mip = u[0] as u16;
                (v.first_slice, v.slices) = clamp_slices(arr, u[1], u[2]);
                if d[1] == 5 {
                    v.plane = u[3] as u16;
                }
            }
            4 => {
                v.mip = u[0] as u16; // TEXTURE2D {Mip, Plane}
                v.plane = u[1] as u16;
                v.slices = 1;
            }
            6 => v.slices = 1, // TEXTURE2DMS
            7 => (v.first_slice, v.slices) = clamp_slices(arr, u[0], u[1]),
            8 => {
                // TEXTURE3D {Mip, FirstW, WSize}
                v.mip = u[0] as u16;
                let depth = (r.desc.depth() >> (u[0].min(15))).max(1);
                (v.first_slice, v.slices) = clamp_slices(depth, u[1], u[2]);
            }
            dim => return Err(format!("RTV view dimension {dim}")),
        }
        Ok(v)
    }

    /// `CreateDepthStencilView(resource, desc)`; `desc` = 6 u32 words
    /// (Format, ViewDimension, Flags, union) or `None`.
    pub fn dsv(r: &Resource, desc: Option<&[u32; 6]>) -> Result<TargetView, String> {
        if r.texture().is_none() {
            return Err("DSV of a buffer".into());
        }
        let Some(d) = desc else {
            let mut v = Self::whole(r, r.mtl_format);
            v.flags = view_flags::IS_DSV;
            return Ok(v);
        };
        let fmt = crate::format::view_format(d[0], r.mtl_format);
        // A DSV always targets the full depth-stencil texture (Metal binds
        // depth and stencil attachments separately from the same texture).
        let fmt = if r.mtl_format == MTLPixelFormat::Depth32Float_Stencil8 { r.mtl_format } else { fmt };
        let mut v = Self::whole(r, fmt);
        v.flags = view_flags::IS_DSV | (d[2] & 3);
        let u = &d[3..];
        let arr = r.desc.array_size();
        match d[1] {
            1 | 3 => {
                v.mip = u[0] as u16; // TEXTURE1D / TEXTURE2D
                v.slices = 1;
            }
            2 | 4 => {
                v.mip = u[0] as u16;
                (v.first_slice, v.slices) = clamp_slices(arr, u[1], u[2]);
            }
            5 => v.slices = 1,
            6 => (v.first_slice, v.slices) = clamp_slices(arr, u[0], u[1]),
            dim => return Err(format!("DSV view dimension {dim}")),
        }
        Ok(v)
    }
}

enum Encoder {
    None,
    Render(Retained<ProtocolObject<dyn MTL4RenderCommandEncoder>>),
    Compute(Retained<ProtocolObject<dyn MTL4ComputeCommandEncoder>>),
}

/// Active GPU predication (`ID3D12GraphicsCommandList::SetPredication`).
#[derive(Clone, Copy, Debug)]
pub struct Predication {
    pub gpu_va: u64,
    /// `0` = `D3D12_PREDICATION_OP_EQUAL_ZERO` (skip when `== 0`),
    /// `1` = `D3D12_PREDICATION_OP_NOT_EQUAL_ZERO` (skip when `!= 0`).
    pub op: u32,
}

/// A deferred whole-subresource `ClearRenderTargetView`/`ClearDepthStencilView`.
#[derive(Clone, Copy, Debug)]
enum ClearKind {
    Color([f32; 4]),
    DepthStencil { depth: Option<f32>, stencil: Option<u8> },
}

#[derive(Clone, Copy, Debug)]
struct PendingClear {
    view: TargetView,
    kind: ClearKind,
    defer_frag_after: MTLStages,
    defer_frag_req: [u32; 7],
}

impl PendingClear {
    fn is_dsv(&self) -> bool {
        matches!(self.kind, ClearKind::DepthStencil { .. })
    }
    /// Same subresource (and for colour, same view format, which defines how
    /// the clear value is encoded).
    fn same_key(&self, v: &TargetView, dsv: bool) -> bool {
        self.is_dsv() == dsv
            && self.view.resource == v.resource
            && self.view.mip == v.mip
            && self.view.first_slice == v.first_slice
            && (dsv || self.view.format == v.format)
    }
}

/// One parsed `D3D12_RESOURCE_BARRIER`.
#[derive(Clone, Copy, Debug)]
pub enum Barrier {
    /// (`*const Resource`, 0 = unknown; StateBefore; StateAfter).
    Transition(usize, u32, u32),
    /// UAV barrier on a resource (0 = all UAV accesses).
    Uav(usize),
    /// Aliasing or anything else: full barrier.
    Full,
}

/// GPU stages that access a resource in D3D12 state `s` (bit set).
pub fn state_stages(s: u32) -> MTLStages {
    use MTLStages as S;
    let pre_raster = S::Vertex | S::Object | S::Mesh | S::Dispatch;
    let shader = pre_raster | S::Fragment;
    if s == 0 {
        return S::All; // COMMON / PRESENT
    }
    let mut m = S::empty();
    let mut rest = s;
    let mut take = |bit: u32, st: S| {
        if s & bit != 0 {
            m |= st;
            rest &= !bit;
        }
    };
    take(0x1, shader); // VERTEX_AND_CONSTANT_BUFFER
    take(0x2, S::Vertex); // INDEX_BUFFER
    take(0x4, S::Fragment); // RENDER_TARGET
    take(0x8, shader | S::AccelerationStructure); // UNORDERED_ACCESS
    take(0x10, S::Fragment); // DEPTH_WRITE
    take(0x20, S::Fragment); // DEPTH_READ
    take(0x40, pre_raster | S::AccelerationStructure); // NON_PIXEL_SHADER_RESOURCE
    take(0x80, S::Fragment); // PIXEL_SHADER_RESOURCE
    take(0x100, S::Vertex); // STREAM_OUT
    take(0x200, pre_raster); // INDIRECT_ARGUMENT / PREDICATION (incl. our expansion kernel)
    take(0x400, S::Blit); // COPY_DEST
    take(0x800, S::Blit); // COPY_SOURCE
    take(0x1000, S::Fragment | S::Blit); // RESOLVE_DEST
    take(0x2000, S::Fragment | S::Blit); // RESOLVE_SOURCE
    take(0x40_0000, S::Dispatch | S::AccelerationStructure); // RAYTRACING_ACCELERATION_STRUCTURE
    if rest != 0 {
        return S::All;
    }
    m
}

/// Strip D3D12 state bits impossible for `r`'s resource dimension (`BUFFER` vs
/// `TEXTURE*`) when `r != 0 && s != 0`, preserving `s` if stripping would empty it.
/// For example, `GENERIC_READ` (`0xAC3`) on a 2D texture drops `VB_CB|IB|INDIRECT_ARG`
/// (`0x203`) -> `0x8C0` (`NON_PIXEL_SRV | PIXEL_SRV | COPY_SRC`).
#[inline]
pub fn filter_res_state_bits(r: usize, s: u32) -> u32 {
    if r == 0 || s == 0 {
        return s;
    }
    const BUF_ONLY: u32 = 0x1 | 0x2 | 0x100 | 0x200 | 0x40_0000;
    const TEX_ONLY: u32 = 0x4 | 0x10 | 0x20 | 0x1000 | 0x2000;
    let is_buf = unsafe { (*(r as *const Resource)).desc.Dimension } == crate::types::dim::BUFFER;
    let filtered = if is_buf { s & !TEX_ONLY } else { s & !BUF_ONLY };
    if filtered != 0 { filtered } else { s }
}

/// Textures (`Dimension != BUFFER`) are never RTAS geometry, instance, scratch,
/// or destination buffers (`MTLStages::AccelerationStructure` operates strictly on `MTLBuffer`s).
#[inline]
fn strip_nonbuf_accel(r: usize, st: MTLStages) -> MTLStages {
    if r != 0
        && st != MTLStages::All
        && unsafe { (*(r as *const Resource)).desc.Dimension } != crate::types::dim::BUFFER
    {
        st - MTLStages::AccelerationStructure
    } else {
        st
    }
}

/// GPU stages accessing `r` in D3D12 state `s`, filtering impossible state bits
/// for `r`'s dimension (`AW2_BARRIER_TIGHT_V2=1`).
#[inline]
pub fn state_stages_for_res(r: usize, s: u32) -> MTLStages {
    strip_nonbuf_accel(r, state_stages(filter_res_state_bits(r, s)))
}

/// Stage-masked barriers (default on; `AW2_BARRIER_MASKS=0` makes every
/// `ResourceBarrier` all → all).
fn barrier_masks() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_BARRIER_MASKS").is_none_or(|v| v != "0"))
}

/// Texture types a layered render pass can clear in one go.
fn layered(t: &super::resource::MtlTexture) -> bool {
    use MTLTextureType as T;
    matches!(t.textureType(), T::Type2DArray | T::TypeCube | T::TypeCubeArray | T::Type2DMultisampleArray | T::Type3D)
}

/// GPU timestamp granularity: relaxed unless `AW2_PRECISE_TIMESTAMPS=1`
/// (precise timestamps can split encoders on Apple GPUs).
fn timestamp_granularity() -> MTL4TimestampGranularity {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    if *ON.get_or_init(|| std::env::var_os("AW2_PRECISE_TIMESTAMPS").is_some_and(|v| v != "0")) {
        MTL4TimestampGranularity::Precise
    } else {
        MTL4TimestampGranularity::Relaxed
    }
}

/// `AW2_LEGACY_BARRIERS=1`: full barrier at every encoder, no deferred clears.
fn legacy_barriers() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_LEGACY_BARRIERS").is_some_and(|v| v != "0"))
}

/// `AW2_RP_DISCARD=1`: a render pass attaching a whole-discarded resource
/// (`DiscardResource`, not written since) skips loading it (DontCare).
fn rp_discard() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_RP_DISCARD").is_some_and(|v| v != "0"))
}

/// Default ON (`AW2_BARRIER_R2R_ELIDE=0` disables): elide no-op (`s0 == s1`)
/// and pure read-to-read D3D12 transitions (`s0 != 0 && s1 != 0 && ((s0 | s1) & WRITE) == 0`).
/// Metal resources have no layout transitions, so read-to-read state changes
/// carry zero memory/execution hazard; any prior write was already ordered by
/// the earlier write-to-read transition.
fn barrier_r2r_elide() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_BARRIER_R2R_ELIDE").is_none_or(|v| v != "0"))
}

/// Default ON (`AW2_BARRIER_TIGHT_STAGES=0` disables): stage-masked barriers
/// for utility dispatches (`upscale_resource` / `clear_uav`) instead of two
/// `MTLStages::All -> MTLStages::All` queue barriers (`qb_clear_uav`).
fn barrier_tight_stages() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_BARRIER_TIGHT_STAGES").is_none_or(|v| v != "0"))
}

/// Default OFF (`AW2_BARRIER_UAV0_KEEP=1` enables): keep deferred RTV/DSV
/// clears across null `Barrier::Uav(0)` barriers instead of force-flushing them
/// (`cf_barrier_uav0` vs `cf_uav0_kept`). Kept opt-in because carrying deferred
/// clears across mid-frame `Uav(0)` barriers can split subsequent render passes.
fn barrier_uav0_keep() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_BARRIER_UAV0_KEEP").is_some_and(|v| v != "0"))
}

/// Default ON (`AW2_IB_TIGHT=0` disables): exact PSV0 + descriptor-table
/// per-resource and stage-masked intra-compute encoder barriers, plus
/// per-resource `compute_clear_batch` / `CopyTextureRegion` / `CopyResource`
/// touch tracking instead of `ib_note(0)` / `produced(Blit, All)`.
pub(crate) fn opt_ib_tight_env() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_IB_TIGHT").is_none_or(|v| v != "0"))
}

/// Default OFF (`AW2_IB_BINDLESS_WAR=1` enables): opt-in Northlight/static-bindless
/// quirk for compute shaders whose only unbounded range is a static-geometry bindless
/// SRV table (`!heap_indexed_or_unknown`): tracks only bounded CBV/SRV slots in
/// `ib_disp_read` instead of conservatively falling back to `None` on SRV->UAV WAR.
/// Kept opt-in so non-Northlight engines with mutable bindless SRV tables never drop WAR barriers.
pub(crate) fn opt_ib_bindless_war_env() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_IB_BINDLESS_WAR").is_some_and(|v| v != "0"))
}

/// Default ON (`AW2_RP_KEEP_WRITE=0` disables): keep an open draw render pass
/// alive across `Barrier::Uav` (when `!pass_uav`) and unattached write-state
/// `Barrier::Transition`s, preserving pass-own WAR obligations in
/// `(rp_write_after, rp_write_before)` upon `end_encoder()`.
pub(crate) fn opt_rp_keep_write_env() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_RP_KEEP_WRITE").is_none_or(|v| v != "0"))
}

/// Default ON (`AW2_CLEAR_KEEP_SMART=0` disables): at `Barrier::Uav(0)`, retain
/// deferred colour RTV clears that `compute_clear_item` can clear via compute
/// (or fold into a later draw pass) while still flushing DSV / non-`ShaderWrite`
/// clears outside render passes unless `AW2_CLEAR_KEEP_DSV=1`.
pub(crate) fn opt_clear_keep_smart_env() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_CLEAR_KEEP_SMART").is_none_or(|v| v != "0"))
}

/// Default ON (`AW2_ICB_BATCH=0` disables): hoist in-pass `ExecuteIndirect` ICB
/// vertex expanders (`aw2_ei_icb_vs_v2`) into a single batched pre-pass burst
/// followed by one `Vertex -> Vertex|Object|Mesh|Fragment` encoder barrier.
pub(crate) fn opt_icb_batch_env() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_ICB_BATCH").is_none_or(|v| v != "0"))
}

/// Default OFF (`AW2_CLEAR_KEEP_DSV=1` enables): retain deferred DSV and
/// non-`ShaderWrite` RTV clears across `Barrier::Uav(0)` (since neither can ever
/// be accessed via UAV) so they do not split open compute encoders mid-list.
pub(crate) fn opt_clear_keep_dsv_env() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_CLEAR_KEEP_DSV").is_some_and(|v| v == "1"))
}

/// Default ON (`AW2_IB_EXACT_OBL=0` disables): narrow intra-compute obligations
/// by destination access kind (`UavOnly`, `UavOrCbv`, `ClassSrv`) so bindless-SRV
/// shaders (`skinning:transformCS`) skip non-conflicting UAV/CBV/class-disjoint barriers.
pub(crate) fn opt_ib_exact_obl_env() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_IB_EXACT_OBL").is_none_or(|v| v != "0"))
}

/// Default OFF (`AW2_LIST_BARRIER_TIGHT=1` enables): replace `FullWhy::ListStart`
/// (`MTLStages::All -> MTLStages::All` on the first encoder of every command list)
/// with Metal 4 stage-masked cross-list synchronization + trailing producer barriers.
pub(crate) fn opt_list_barrier_tight_env() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("AW2_LIST_BARRIER_TIGHT").is_some_and(|v| v == "1"))
}

/// Default OFF (`AW2_BARRIER_TIGHT_V2=1` enables): soft pre-raster deferral on
/// kept render write/UAV barriers (`rp_write_soft`), resource-dimension state
/// filtering (`GENERIC_READ` on textures), `render_mid_barrier` `vtx_defer`,
/// and `GENERIC_READ` (`0x200`/`0x800`) `OblKind` refinement in compute.
