/// Transitive queue-barrier synchronization watermark per Metal stage (`g34` / `g35` / `g47`).
#[derive(Clone, Copy, Debug)]
struct StageSync {
    pre_list_all: bool,
    pre_list_stages: MTLStages,
    gen: [u32; 7],
    disp_gen: u32,
    as_gen: u32,
    gfx_uav_gen: u32,
}

impl Default for StageSync {
    #[inline]
    fn default() -> Self {
        Self {
            pre_list_all: false,
            pre_list_stages: MTLStages::empty(),
            gen: [0; 7],
            disp_gen: 0,
            as_gen: 0,
            gfx_uav_gen: 0,
        }
    }
}

impl StageSync {
    #[inline]
    fn merge(&mut self, other: Self) {
        self.pre_list_all |= other.pre_list_all;
        self.pre_list_stages |= other.pre_list_stages;
        for i in 0..7 {
            self.gen[i] = self.gen[i].max(other.gen[i]);
        }
        self.disp_gen = self.disp_gen.max(other.disp_gen);
        self.as_gen = self.as_gen.max(other.as_gen);
        self.gfx_uav_gen = self.gfx_uav_gen.max(other.gfx_uav_gen);
    }
}

/// One pending intra-compute obligation (`AW2_IB_TIGHT=1`).
#[derive(Clone, Debug)]
struct IbObl {
    /// `*const Resource` (`0` = any resource).
    r: usize,
    /// Encoder stages in the current compute encoder whose prior work must finish.
    after: MTLStages,
    /// Encoder stages in the current compute encoder that must wait if touching `r`.
    before: MTLStages,
    /// Destination access kind for `AW2_IB_EXACT_OBL=1`.
    kind: OblKind,
    /// Optional exact GPU-VA byte `[lo, hi)` sub-ranges touched on buffer `r` (`AW2_SUBRANGE_UAV_BARRIER=1`).
    spans: Option<Vec<SubRange>>,
}

#[derive(Clone, Copy)]
struct DispatchExact<'a> {
    uav_exact: bool,
    full_read_exact: bool,
    bounded_read_exact: bool,
    touches_textures: bool,
    unbounded_srv_classes: u8,
    uav_classes: u8,
    read_classes: u8,
    exact_read_only_classes: u8,
    uav_srv_classes: u8,
    hk: super::pipeline::HandleKindProfile,
    uavs: &'a [usize],
    bounded_reads: &'a [usize],
    uav_spans: Option<&'a [SubRange]>,
    bounded_read_spans: Option<&'a [SubRange]>,
}

struct DynSnapshot {
    viewports: Vec<MTLViewport>,
    scissors: Vec<Rect>,
    blend_factor: [f32; 4],
    stencil_ref: u32,
    stencil_back_ref: u32,
}

struct DirectBind {
    heaps: [u64; 2],
    root: u64,
    pa: u64,
    ia: u64,
    vbs: Vec<(u32, u64, usize)>,
}

#[derive(Default)]
struct CsBindCache {
    valid: bool,
    pso_ptr: usize,
    want_spans: bool,
    want_bounded: bool,
    reg_gen: u64,
    desc_gen: u64,
    root_gen: u64,
    heap0_base: u64,
    tokens: Vec<u64>,
    uav_exact: bool,
    full_read_exact: bool,
    bounded_read_exact: bool,
    uavs: Vec<usize>,
    reads: Vec<usize>,
    uav_spans: Vec<SubRange>,
    read_spans: Vec<SubRange>,
}

impl CsBindCache {
    #[inline]
    fn matches_gen(
        &self,
        pso_ptr: usize,
        want_spans: bool,
        reg_gen: u64,
        desc_gen: u64,
        root_gen: u64,
        heap0_base: u64,
    ) -> bool {
        self.valid
            && self.pso_ptr == pso_ptr
            && self.want_spans == want_spans
            && self.want_bounded
            && self.reg_gen == reg_gen
            && self.desc_gen == desc_gen
            && self.root_gen == root_gen
            && self.heap0_base == heap0_base
    }

    #[inline]
    fn matches_tokens(
        &self,
        pso_ptr: usize,
        want_spans: bool,
        want_bounded: bool,
        reg_gen: u64,
        heap0_base: u64,
        tokens: &[u64],
    ) -> bool {
        self.valid
            && self.pso_ptr == pso_ptr
            && self.want_spans == want_spans
            && self.want_bounded == want_bounded
            && self.reg_gen == reg_gen
            && self.heap0_base == heap0_base
            && self.tokens == tokens
    }

    #[allow(clippy::too_many_arguments)]
    #[inline]
    fn store(
        &mut self,
        pso_ptr: usize,
        want_spans: bool,
        want_bounded: bool,
        reg_gen: u64,
        desc_gen: u64,
        root_gen: u64,
        heap0_base: u64,
        tokens: &[u64],
        uav_exact: bool,
        full_read_exact: bool,
        bounded_read_exact: bool,
        uavs: &[usize],
        reads: &[usize],
        uav_spans: &[SubRange],
        read_spans: &[SubRange],
    ) {
        self.valid = true;
        self.pso_ptr = pso_ptr;
        self.want_spans = want_spans;
        self.want_bounded = want_bounded;
        self.reg_gen = reg_gen;
        self.desc_gen = desc_gen;
        self.root_gen = root_gen;
        self.heap0_base = heap0_base;
        self.tokens.clear();
        self.tokens.extend_from_slice(tokens);
        self.uav_exact = uav_exact;
        self.full_read_exact = full_read_exact;
        self.bounded_read_exact = bounded_read_exact;
        self.uavs.clear();
        self.uavs.extend_from_slice(uavs);
        self.reads.clear();
        self.reads.extend_from_slice(reads);
        self.uav_spans.clear();
        if want_spans {
            self.uav_spans.extend_from_slice(uav_spans);
        }
        self.read_spans.clear();
        if want_spans {
            self.read_spans.extend_from_slice(read_spans);
        }
    }
}

